import {formatMarketDepth} from './market-depth.js?v=babbc3d3950e';
import {formatMoney} from './money.js?v=babbc3d3950e';
import {FACTIONS} from './economy.js?v=babbc3d3950e';
import {commodityName,supplyUnits} from './port-supplies.js?v=babbc3d3950e';
import {axialToWorld} from './world.js?v=babbc3d3950e';
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
export class BridgeUI {
 constructor({app,parent,getTraffic,getPlayer}){
  Object.assign(this,{getTraffic,getPlayer});this.heat=new PIXI.Graphics();this.heat.eventMode='none';app.stage.addChild(this.heat);this.faction=null;
  this.controls=el('div');this.controls.className='bridge-controls';this.ledgerButton=el('button','View Ledger');this.ledgerButton.onclick=()=>this.open('ledger');const diplomacy=el('button','Diplomacy (D)');diplomacy.onclick=()=>this.open('diplomacy');this.controls.append(this.ledgerButton,diplomacy);
  const label=el('p','Threat perspective · F1–F4');this.controls.append(label);this.heatButtons=FACTIONS.map((f,i)=>{const b=el('button',`${f[0]+f.slice(1).toLowerCase()} (F${i+1})`);b.onclick=()=>this.toggle(f);this.controls.append(b);return b;});this.note=el('p');this.note.setAttribute('role','status');this.controls.append(this.note);parent.append(this.controls);
  this.dialog=el('dialog');this.dialog.className='bridge-dialog';this.title=el('h2');this.body=el('div');const close=el('button','Close');close.onclick=()=>this.dialog.close();this.dialog.append(this.title,close,this.body);document.body.append(this.dialog);
  window.addEventListener('keydown',e=>{if(this.dialog.open){e.stopImmediatePropagation();if(e.key==='Escape'){e.preventDefault();this.dialog.close();}return;}if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.target.isContentEditable||e.ctrlKey||e.metaKey||e.altKey)return;if(/^F[1-4]$/.test(e.key)){e.preventDefault();this.toggle(FACTIONS[Number(e.key.slice(1))-1]);}else if(e.key.toLowerCase()==='d'){e.preventDefault();this.open('diplomacy');}},{capture:true});this.refresh();
 }
 toggle(f){this.faction=this.faction===f?null:f;this.getTraffic().setHeatmap(this.faction);this.heat.clear();this.heatKey=null;this.refresh();}
 open(mode){if(!this.getTraffic()?.worker)return;if(mode==='ledger'&&!this.getPlayer()?.docked)return;this.mode=mode;this.contentKey=null;this.refresh();if(!this.dialog.open)this.dialog.showModal();}
 table(headers,rows){const table=el('table');const head=el('tr');for(const h of headers)head.append(el('th',h));table.append(head);for(const values of rows){const row=el('tr');for(const v of values)row.append(el('td',String(v)));table.append(row);}return table;}
 refresh(){const traffic=this.getTraffic(),s=traffic?.bridgeState;if(this.worker!==traffic?.worker){this.worker=traffic?.worker;if(this.worker&&this.faction)traffic.setHeatmap(this.faction);}this.ledgerButton.hidden=!this.getPlayer()?.docked;for(const [i,b] of this.heatButtons.entries()){b.setAttribute('aria-pressed',String(this.faction===FACTIONS[i]));b.disabled=!traffic?.worker;}this.note.textContent=this.faction?`${this.faction}: hostile threat yellow/red; patrol security blue · ${(s?.threat??[]).length} active hexes`:'Threat overlay off';if(!s||!this.mode)return;const key=JSON.stringify([this.mode,s.tick,s.playerLedger,s.diplomacy]);if(key===this.contentKey)return;this.contentKey=key;this.body.replaceChildren();
  if(this.mode==='ledger'){this.title.textContent='Ship price ledger';this.body.append(el('p',`Knowledge at tick ${s.tick}. Prices include observation age; older reports have lower confidence. Expired reports are removed.`));if(!s.playerLedger.length)this.body.append(el('p','No market reports yet. Dock to exchange information.'));for(const entry of s.playerLedger){const block=el('section');block.className=entry.confidence<=.25?'ledger-stale':entry.confidence<=.5?'ledger-aging':'';block.append(el('h3',entry.portName),el('p',`Age ${entry.age} ticks · ${Math.round(entry.confidence*100)}% confidence · observed at ${entry.originPortId} · tick ${entry.tick}`),this.table(['Commodity','Supply asks: quantity @ price (seller)','Funded bids: quantity @ price (buyer)'],Object.entries(entry.prices).map(([c,v])=>[commodityName(c),formatMarketDepth(v.offers,'ask'),formatMarketDepth(v.orders,'bid')])));this.body.append(block);}}
  else{this.title.textContent='Diplomacy';this.body.append(el('p','Current symmetric faction relationships. War or negative standing prevents merchant destinations; embargoes prevent trade.'));for(const [name,field] of [['Standings','standing'],['War declarations','war'],['Alliances','alliance'],['Trade embargoes','embargo']]){this.body.append(el('h3',name),this.table(['Faction',...FACTIONS],s.diplomacy.map(row=>[row.faction,...row.relations.map(r=>field==='standing'?r.standing:r[field]?'Yes':'No')])));}}
 }
 render(camera,scale,width,height){const state=this.getTraffic()?.bridgeState,cells=state?.heatFaction===this.faction?state.threat:[],key=[this.faction,state?.heatFaction,state?.tick,camera.x,camera.y,scale,width,height].join(':');if(key===this.heatKey)return;this.heatKey=key;this.heat.clear();if(!this.faction||!this.getTraffic()?.worker)return;for(const c of cells){const p=axialToWorld(c.q,c.r),x=(p.x-camera.x)*scale+width/2,y=(p.y-camera.y)*scale+height/2;if(x<-scale||y<-scale||x>width+scale||y>height+scale)continue;const v=Math.min(1,c.value/state.maxThreat),security=c.security??0,points=[];for(let i=0;i<6;i++){const angle=(i*60-90)*Math.PI/180;points.push(x+Math.cos(angle)*scale*.94,y+Math.sin(angle)*scale*.94);}this.heat.poly(points).fill({color:v>.01?(v>.5?0xef4444:0xfbbf24):0x38bdf8,alpha:v>.01?.12+.5*v:.08+.35*security});}}
}
